	@Test
	void repeatedEvaluationUsesCurrentGraphForEdgesAndIdentityMembership() {
		TrackingSource source = new TrackingSource();
		IRI graphA = VF.createIRI(NS + "graphA");
		IRI graphB = VF.createIRI(NS + "graphB");
		IRI predicateOnly = VF.createIRI(NS + "predicateOnly");
		Value objectOnly = VF.createLiteral("object only");
		source.model.add(node(0), PREDICATE, node(1), graphA);
		source.model.add(node(1), PREDICATE, node(2), graphA);
		source.model.add(node(3), predicateOnly, objectOnly, graphB);
		class SwitchingGraphContext extends QueryEvaluationContext.Minimal {
			private ActiveGraph graph = new ActiveGraph(graphA, graphA);

			SwitchingGraphContext() {
				super(null);
			}

			@Override
			public ActiveGraph getActiveGraph() {
				return graph;
			}
		}
		SwitchingGraphContext context = new SwitchingGraphContext();
		CountingStrategy strategy = new CountingStrategy(source);
		QueryEvaluationStep path = strategy.precompile(unboundPath(0), context);
		QueryEvaluationStep identity = strategy.precompile(new ZeroLengthPath(Var.of("s"), Var.of("o")), context);
		QueryEvaluationContext.ActiveGraph selectedA = context.graph;
		QueryEvaluationContext.ActiveGraph selectedB = new QueryEvaluationContext.ActiveGraph(graphB, graphB);
		try (var rows = path.evaluate(input(0, "before-first-pull"))) {
			context.graph = selectedB;
			assertThat(collect(rows)).isEmpty();
		}
		context.graph = selectedA;
		try (var rows = path.evaluate(input(0, "graphA"))) {
			assertThat(collect(rows)).containsExactlyInAnyOrder(taggedRow(0, 0, "graphA"),
					taggedRow(0, 1, "graphA"), taggedRow(0, 2, "graphA"));
		}
		try (var rows = identity.evaluate(input(0, "graphA"))) {
			assertThat(collect(rows)).containsExactly(taggedRow(0, 0, "graphA"));
		}
		context.graph = selectedB;
		try (var rows = path.evaluate(input(0, "graphB"))) {
			assertThat(collect(rows)).isEmpty();
		}
		try (var rows = identity.evaluate(input(0, "graphB"))) {
			assertThat(collect(rows)).isEmpty();
		}
		QueryBindingSet fromPredicate = new QueryBindingSet();
		fromPredicate.addBinding("s", predicateOnly);
		try (var rows = path.evaluate(fromPredicate)) {
			assertThat(collect(rows)).isEmpty();
		}
		QueryBindingSet fromObject = new QueryBindingSet();
		fromObject.addBinding("s", objectOnly);
		try (var rows = path.evaluate(fromObject)) {
			assertThat(collect(rows)).singleElement()
					.satisfies(row -> assertThat(row.getValue("o")).isEqualTo(objectOnly));
		}
		assertThat(source.closed).isEqualTo(source.opened);
	}

	@ParameterizedTest
	@ValueSource(strings = { "*", "+" })
	void blankNodeFrontierRetainsItsFixedReferenceReservation(String operator) {
		TrackingSource source = new TrackingSource();
		var middle = VF.createBNode("stored-middle");
		source.model.add(node(0), PREDICATE, middle);
		source.model.add(middle, PREDICATE, node(2));
		CountingStrategy strategy = new CountingStrategy(source);
		QueryEvaluationStep prepared = strategy.precompile(parse(
				"SELECT (BNODE() AS ?fresh) WHERE { :n0 :edge" + operator + " :n2 }"));
		// This source cannot check stored blank-node IDs. A fixed frontier reference must not silently
		// become an ordinary runtime binding that would allow an unchecked fresh-node allocation.
		assertThatThrownBy(() -> {
			try (var result = prepared.evaluate(EmptyBindingSet.getInstance())) {
				collect(result);
			}
		}).isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("Unsupported blank-node identity: backend cannot check stored IDs");
		assertThat(source.closed).isEqualTo(source.opened);
	}

	@ParameterizedTest
	@ValueSource(strings = { "*", "+" })
	void apiOriginBlankNodeFrontierRemainsARuntimeReservation(String operator) {
		BNode middle = VF.createBNode("runtime-middle");
		TrackingSource source = twoHopSource(middle);
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("s", node(0));
		TupleExpr expression = parse("SELECT (BNODE() AS ?fresh) WHERE { ?s :edge" + operator + " :n2 }");
		new BindingAssignerOptimizer().optimize(expression, null, input);
		List<ArbitraryLengthPath> paths = new ArrayList<>();
		expression.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ArbitraryLengthPath path) {
				paths.add(path);
			}
		});
		assertThat(paths).hasSize(1);
		ArbitraryLengthPath path = paths.getFirst();
		assertThat(path.getSubjectVar().hasApiInputOrigin()).isTrue();
		assertThat(path.getPathExpression()).isInstanceOfSatisfying(StatementPattern.class,
				pattern -> assertThat(pattern.getSubjectVar().hasApiInputOrigin()).isTrue());
		CountingStrategy strategy = new CountingStrategy(source);
		try (var result = strategy.precompile(expression).evaluate(input)) {
			assertThat(collect(result)).singleElement()
					.satisfies(row -> assertThat(row.getValue("fresh"))
							.isInstanceOf(BNode.class)
							.isNotEqualTo(middle));
		}
		assertThat(source.closed).isEqualTo(source.opened);
	}

	@ParameterizedTest
	@ValueSource(strings = { "*", "+" })
	void remoteBlankNodeFrontierKeepsItsAuthorityWithoutBecomingAFixedReference(String operator) {
		Object epoch = new Object();
		BNode remote = VF.createBNode("canonical");
		BNode middle = (BNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, epoch, true)
				.map(remote);
		TrackingSource source = twoHopSource(middle);
		List<Resource> observed = new ArrayList<>();
		TripleSource authorityCheckingSource = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				if (middle.equals(subject)) {
					assertThat(RemoteBNode.containsRemoteIdentity(subject)).isTrue();
					assertThat(RemoteBNode.toRemoteValue(subject, epoch, true, true)).isEqualTo(remote);
					observed.add(subject);
				}
				return source.getStatements(subject, predicate, object, contexts);
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		CountingStrategy strategy = new CountingStrategy(authorityCheckingSource);
		QueryEvaluationStep prepared = strategy.precompile(parse(
				"SELECT (BNODE() AS ?fresh) WHERE { :n0 :edge" + operator + " :n2 }"));
		try (var result = prepared.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(collect(result)).singleElement()
					.satisfies(row -> assertThat(row.getValue("fresh"))
							.isInstanceOf(BNode.class)
							.isNotEqualTo(middle));
		}
		assertThat(observed).as("the remote frontier must be checked when its outgoing edge is probed").isNotEmpty();
		assertThat(source.closed).isEqualTo(source.opened);
	}

